<script setup lang="ts">
import {ask} from './confirm';
import XiaomiAccounts from './XiaomiAccounts.vue';
import {serviceGroups,serviceSummary} from './device-services';
import {ref,onMounted,computed} from 'vue';import {api,ApiError} from './api';import Dialog from './Dialog.vue';import SchemaForm from './SchemaForm.vue';import ResultView from './ResultView.vue';
const xiaomiOpen=ref(false);const manualTemplates=computed(()=>templates.value.filter(t=>t.creation_mode!=='discovery'));
const emit=defineEmits(['message']);const devices=ref<any[]>([]),templates=ref<any[]>([]),edit=ref<any>(null),selected=ref<any>(null),invoke=ref<any>(null),params=ref<any>({}),result=ref<any>(null),busy=ref(false),error=ref(''),connections=ref<any[]>([]),discovering=ref(false),discoveryError=ref('');
const template=computed(()=>templates.value.find(t=>t.key===edit.value?.template_key));
async function load(){try{[devices.value,templates.value]=await Promise.all([api('/admin/devices'),api('/admin/access-templates')])}catch(e:any){emit('message',e.message)}}onMounted(load);
function defaults(t:any){return Object.fromEntries(Object.entries(t.config_schema.properties).filter(([,v]:any)=>v.default!==undefined).map(([k,v]:any)=>[k,v.default]))}
async function discover(){connections.value=[];discoveryError.value='';if(!edit.value?.template_key)return;discovering.value=true;try{connections.value=await api('/admin/access-templates/'+edit.value.template_key+'/connections')}catch(e:any){discoveryError.value=e.message}finally{discovering.value=false}}
function chooseTemplate(){edit.value.connection_config=defaults(template.value);discover()}
const connection=computed(()=>connections.value.find(c=>c.value===edit.value?.connection_config[template.value?.connection_field]));
function chooseConnection(event:Event){const value=(event.target as HTMLSelectElement).value;if(value)edit.value.connection_config[template.value.connection_field]=value}
const modes:Record<string,string>={usb_identity:'按USB唯一序列号跟随',usb_port:'固定USB插口',path:'手动路径'};
function create(){error.value='';const t=manualTemplates.value[0];edit.value={template_key:t.key,display_name:'',connection_config:defaults(t)};discover()}
async function editing(d:any){error.value='';try{const v=await api('/admin/devices/'+d.id);const template_key=v.device.template_key;edit.value={...v.device,connection_config:v.connection_config,template_key};await discover()}catch(e:any){emit('message',e.message)}}
async function save(){busy.value=true;error.value='';try{const d=edit.value;await api('/admin/devices'+(d.id?'/'+d.id:''),d.id?'PATCH':'POST',d.id?{display_name:d.display_name,connection_config:d.connection_config,revision:d.revision}:{template_key:d.template_key,display_name:d.display_name,connection_config:d.connection_config});edit.value=null;await load();emit('message','设备配置已保存')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function test(d:any){busy.value=true;try{await api(`/admin/devices/${d.id}/connection-test`,'POST',{});emit('message','只读连接测试通过')}catch(e:any){emit('message',e.code+'：'+e.message)}finally{busy.value=false;await load()}}
async function refreshCapabilities(d:any){busy.value=true;try{const updated=await api(`/admin/devices/${d.id}/refresh-capabilities`,'POST',{});if(selected.value?.id===d.id){selected.value=updated;invoke.value=null;result.value=null}await load();emit('message','设备能力已更新，设备身份与项目绑定已保留')}catch(e:any){emit('message',e.message)}finally{busy.value=false}}
function canRefresh(d:any){return templates.value.some(t=>t.key===d.template_key&&t.can_refresh_capabilities)}
async function remove(d:any){if(!await ask('删除设备“'+d.display_name+'”？存在项目引用时会拒绝，删除不会改变物理输出。'))return;try{await api('/admin/devices/'+d.id,'DELETE');await load();selected.value=null;edit.value=null}catch(e:any){emit('message',e.message)}}
function call(s:any){invoke.value=s;params.value={};result.value=null;error.value=''}
async function execute(){busy.value=true;error.value='';try{result.value=await api(`/admin/devices/${selected.value.id}/services/${invoke.value.key}/invoke`,'POST',{parameters:params.value})}catch(e:any){error.value=e.code+'：'+e.message;if(e instanceof ApiError)result.value=e.record}finally{busy.value=false;await load()}}
</script>
<template><section><div class="section-title"><div><p class="eyebrow">DEVICE ACCESS</p><h1>设备管理</h1><p class="muted">连接设备，查看能力与通信状态。</p></div><div class="row wrap"><button @click="xiaomiOpen=true">小米账号与设备</button><button class="primary" @click="create" :disabled="!manualTemplates.length">＋ 添加设备</button></div></div><div class="stat-strip"><span><b>{{devices.length}}</b> 台设备</span><span><i class="dot online"></i> {{devices.filter(d=>d.availability==='online').length}} 台在线</span><button class="text-button" @click="load">刷新列表 ↻</button></div><div v-if="!devices.length" class="empty"><h2>连接第一台设备</h2><p>可以配置串口设备，或连接小米账号后勾选开关设备。暂时离线也可以保留设备。</p><button @click="create" :disabled="!manualTemplates.length">添加设备</button></div><div class="card-grid"><article v-for="d in devices" :key="d.id" class="card device-card"><div class="row spread"><span class="device-mark">⌁</span><span class="badge" :class="d.availability==='online'?'online':'error'">{{d.availability==='online'?'在线':d.availability==='unknown'?'状态待确认':'离线'}}</span></div><h2>{{d.display_name}}</h2><p class="muted">{{serviceSummary(d.services)}}</p><p v-if="d.last_error" class="error-text small">{{d.last_error}}</p><div class="card-actions"><button @click="selected=d;invoke=null;result=null">服务与调试</button><button @click="editing(d)">配置</button><button @click="test(d)" :disabled="busy">连接测试</button><button v-if="canRefresh(d)" @click="refreshCapabilities(d)" :disabled="busy">刷新设备能力</button><button class="danger" @click="remove(d)" :disabled="busy">删除设备</button></div></article></div>
<Dialog v-if="edit" :title="edit.id?'编辑设备':'添加设备'" @close="if(!busy)edit=null;"><form @submit.prevent="save"><label>设备名称<input v-model="edit.display_name" required maxlength="100"></label><label>接入模板<select v-model="edit.template_key" :disabled="!!edit.id" @change="chooseTemplate"><option v-for="t in (edit.id?templates:manualTemplates)" :value="t.key" :key="t.key">{{t.title}}</option></select></label><section v-if="template?.connection_field" class="connection-selector"><div class="row spread"><h3>{{edit.id?'重新选择串口':'选择串口绑定'}}</h3><button type="button" @click="discover" :disabled="discovering">{{discovering?'读取中…':'刷新串口'}}</button></div><label>可用串口<select :value="connection?.value||''" @change="chooseConnection"><option value="">手动填写或保留当前路径</option><option v-for="c in connections" :key="c.value" :value="c.value" :disabled="!c.selectable">{{modes[c.mode]||c.mode}} · {{c.label}}{{c.selectable?'':'（不可可靠绑定）'}}</option></select></label><p v-if="connection" class="meta">绑定方式：{{modes[connection.mode]}}<br>当前节点：{{connection.resolved_path}}<br>{{connection.warning||'在唯一USB身份不变时可跟随串口编号和插口变化；仪器身份仍由驱动另行校验。'}}</p><p v-else class="meta">可以直接输入by-id、by-path或手动串口路径；离线时保留已保存的路径。按编号配置可能随插拔变化。</p><p v-if="connections.some(c=>!c.selectable)" class="notice">部分by-id没有唯一序列号或存在多个候选，已禁止选择。此类设备可使用固定USB插口绑定。</p><p v-if="discoveryError" class="error-text">{{discoveryError}}</p><p v-if="edit.id" class="notice">重新选择串口会保留设备身份、项目服务绑定和Token。通信忙碌时不能修改；已有仪器序列号校验继续生效。</p></section><p v-if="template?.creation_mode==='discovery'" class="notice">此设备由账号导入，账号和设备身份保持固定。这里可以修改显示名称；更换设备请重新导入并显式改绑项目。</p><SchemaForm v-if="template && template.creation_mode!=='discovery'" :schema="template.config_schema" :first-field="template.connection_field" v-model="edit.connection_config" prefix="device"/><p v-if="error" role="alert" class="error-text">{{error}}</p><footer class="form-actions"><button type="button" @click="edit=null" :disabled="busy">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存设备'}}</button></footer></form></Dialog>
<Dialog v-if="selected" :title="selected.display_name+' · 服务调试'" @close="if(!busy)selected=null;"><p class="notice">所有调试使用同一设备执行器。操作会改变实际设备状态，通信冲突立即报错。</p><section v-for="group in serviceGroups(selected.services)" :key="group.key"><h3 v-if="group.title">{{group.title}}</h3><div class="service-picker"><button v-for="s in group.services" :key="s.key" :class="{chosen:invoke?.key===s.key}" @click="call(s)" :disabled="busy">{{s.title}} <small>{{s.kind==='read'?'读取':'操作'}}</small></button></div></section><form v-if="invoke" @submit.prevent="execute"><h3>{{invoke.title}}</h3><SchemaForm :schema="invoke.input_schema" v-model="params" prefix="debug"/><p v-if="error" role="alert" class="error-text">{{error}}</p><button class="primary" :disabled="busy">{{busy?'通信中…':'执行设备服务'}}</button></form><ResultView :record="result"/><div class="form-actions"><button @click="editing(selected);selected=null" :disabled="busy">编辑连接</button><button class="danger" @click="remove(selected)" :disabled="busy">删除设备</button></div></Dialog><XiaomiAccounts v-if="xiaomiOpen" @close="xiaomiOpen=false" @changed="load" @message="emit('message',$event)"/></section></template>
